(()=>{'use strict';let record=null,loading=null;async function request(body){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),12000);try{const r=await fetch('/api/academy',{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:ctrl.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const value=await r.json();if(!r.ok)throw Error(value.error||'Account memory unavailable');return value;}finally{clearTimeout(timer);}}window.CodeTrailMemory={async load(){if(loading)return loading;loading=request().then(r=>{record=r;return r.state.memory;}).catch(()=>{record=null;return null;}).finally(()=>loading=null);return loading;},snapshot(){return record?{account:record.account,epoch:record.state.memory.epoch,enabled:record.state.memory.enabled,notes:record.state.memory.notes,turns:record.state.memory.turns}:null;},async append(start,user,assistant,context){if(!start?.enabled)return{saved:false,disabled:true};try{const r=await request({account:start.account,action:'memoryAppend',epoch:start.epoch,id:crypto.randomUUID(),user:user.slice(0,3000),assistant:assistant.slice(0,12000),context:context.slice(0,160)});record=r;return{saved:true};}catch(e){return{saved:false,error:e.message};}}};})();
